// The food database the app searches and logs from. Three layers, later ones win by id:
//  1. LEGACY: the hand-made Chick-fil-A / Panda list this tool started with, plus the shake and custom pseudo-items.
//     Kept so every id ever logged still resolves (logs store ids; rename `name` freely, never change an `id`).
//  2. The bundled catalog (data/catalog.ts, generated by packages/food-data): every chain, home staples, and the
//     most-scanned store products, with photos in assets/menu/catalog/.
//  3. The full catalog, downloaded on demand from UploadThing (store/catalog.ts): tens of thousands of store products,
//     photos by URL.
// `byId` is one mutable map over all three; `registerItems` extends it when the download loads.
import { CATALOG_JSON } from './catalog.ts';

export type Restaurant = string; // a place id: 'cfa', 'mcd', 'store', 'home', 'shake', 'custom'…
export type Category =
  | 'entree' | 'base' | 'side' | 'appetizer' | 'drink' | 'sauce' | 'dessert' | 'breakfast' // chains
  | 'snack' | 'dairy' | 'meat' | 'frozen' | 'bakery' | 'produce' | 'pantry' | 'meal' | 'protein' // stores and home
  | 'shake' | 'custom';
export const CATEGORY_NAMES: Record<Category, string> = {
  entree: 'Entrées', base: 'Bases', side: 'Sides', appetizer: 'Appetizers', drink: 'Drinks', sauce: 'Sauces', dessert: 'Desserts', breakfast: 'Breakfast',
  snack: 'Snacks', dairy: 'Dairy & Eggs', meat: 'Meat & Fish', frozen: 'Frozen', bakery: 'Bread & Bakery', produce: 'Fruit & Veg', pantry: 'Pantry', meal: 'Meals', protein: 'Protein',
  shake: 'Shake', custom: 'Custom',
};
export type MenuItem = {
  id: string;
  restaurant: Restaurant;
  name: string;
  kcal: number | null; // null = user-set (protein shake)
  category: Category;
  image?: string; // key into IMAGES (legacy photos) or CATALOG_IMAGES (bundled catalog)
  url?: string; // photo by URL (downloaded catalog)
  fit?: 'contain'; // product cutout on white: pad it instead of filling the tile
  p?: number; c?: number; f?: number; // protein, carbs, fat in grams (not set for the shake: you set that)
  na?: number; // sodium, mg
  serving?: string; // what one of it is: "1 bottle (12 fl oz)"
  grams?: number;
  brand?: string;
};
export type Place = { id: Restaurant; name: string; kind: 'fast' | 'store' | 'home' | 'app' };
// How a place sells a meal: slots filled in order, plus optional add-ons (one category or several).
export type Order = { slots: Category[]; extras?: Category | Category[] } | null;
export const extrasOf = (o: NonNullable<Order>): Category[] => (Array.isArray(o.extras) ? o.extras : o.extras ? [o.extras] : []);

// What packages/food-data exports. `image` is "images/<id>.jpg" in the bundled copy (the photo is in CATALOG_IMAGES) and a full URL in the downloaded one.
export type Catalog = {
  version: string;
  places: { id: string; name: string; kind: 'fast' | 'store' | 'home'; orders?: Record<string, Order> }[];
  items: { id: string; place: string; name: string; category: Category; kcal: number; p?: number; c?: number; f?: number; na?: number; serving?: string; grams?: number; brand?: string; image?: string; fit?: 'contain' }[];
};
const bundled: Catalog = JSON.parse(CATALOG_JSON);

