const LEGACY_PLACES: Place[] = [{ id: 'cfa', name: 'Chick-fil-A', kind: 'fast' }, { id: 'panda', name: 'Panda Express', kind: 'fast' }, { id: 'shake', name: 'Protein shake', kind: 'app' }, { id: 'custom', name: 'Custom calories', kind: 'app' }];
const LEGACY_ORDERS: Record<string, Record<string, Order>> = {
  cfa: { 'À la carte': null, Meal: { slots: ['entree', 'side', 'drink'], extras: 'sauce' } },
  panda: { 'À la carte': null, Bowl: { slots: ['base', 'entree'] }, Plate: { slots: ['base', 'entree', 'entree'] }, 'Bigger Plate': { slots: ['base', 'entree', 'entree', 'entree'] } },
};

// A catalog item as the app sees it. Bundled items' photos are keyed by id in CATALOG_IMAGES; the downloaded
// catalog's `image` is already a full URL (remote = true).
export function fromCatalog(i: Catalog['items'][number], remote = false): MenuItem {
  const { place, image, ...rest } = i;
  const out: MenuItem = { ...rest, restaurant: place };
  if (image) {
    if (remote) out.url = image;
    else out.image = i.id;
  }
  return out;
}

export const PLACES: Record<Restaurant, Place> = Object.fromEntries([...LEGACY_PLACES, ...bundled.places.map(p => ({ id: p.id, name: p.name, kind: p.kind }))].map(p => [p.id, p]));
export const ORDERS: Record<Restaurant, Record<string, Order>> = { ...LEGACY_ORDERS, ...Object.fromEntries(bundled.places.filter(p => p.orders).map(p => [p.id, p.orders!])) };
// Every item, in one map. Layers 2 and 3 extend it: `registerItems` keeps `byId` and `MENU` in step.
export const byId: Record<string, MenuItem> = {};
export const MENU: MenuItem[] = [];
export function registerItems(items: MenuItem[]) {
  for (const it of items) {
    const old = byId[it.id];
    if (!old) MENU.push(it);
    else {
      if (!it.image && !it.url && old.image) it.image = old.image; // a newer entry without a photo keeps the one we had
      MENU[MENU.indexOf(old)] = it;
    }
    byId[it.id] = it;
  }
}
registerItems(LEGACY);
registerItems(bundled.items.map(i => fromCatalog(i)));
export const CATALOG_VERSION = bundled.version;
export const itemsOf = (place: Restaurant) => MENU.filter(m => m.restaurant === place);
